<?php
declare(strict_types=1); require __DIR__.'/_bootstrap.php';
$count=(int)$pdo->query('SELECT COUNT(*) FROM admin_users')->fetchColumn(); if($count>0) redirect_to('login.php'); $error='';
if(is_post()){verify_csrf($_POST['csrf']??'');$key=(string)($_POST['setup_key']??'');$u=trim((string)($_POST['username']??''));$p=(string)($_POST['password']??'');if(!hash_equals((string)($config['admin']['setup_key']??''),$key))$error='Invalid setup key.';elseif(!preg_match('/^[A-Za-z0-9_.-]{4,80}$/',$u))$error='Username must be 4–80 characters.';elseif(strlen($p)<10)$error='Password must be at least 10 characters.';else{$s=$pdo->prepare('INSERT INTO admin_users(username,password_hash) VALUES(?,?)');$s->execute([$u,password_hash($p,PASSWORD_DEFAULT)]);flash('success','Administrator created. You can now sign in.');redirect_to('login.php');}}
?>
